package com.example.urlshortener.controller;
import com.example.urlshortener.dto.*; import com.example.urlshortener.service.WorkflowEngine; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@RestController @RequestMapping("/workflow") public class WorkflowController { private final WorkflowEngine engine; public WorkflowController(WorkflowEngine engine){this.engine=engine;} @PostMapping("/start") public WorkflowDetailsResponse start(@Valid @RequestBody WorkflowStartRequest request){return engine.start(request);} @GetMapping("/{id}") public WorkflowDetailsResponse get(@PathVariable UUID id){return engine.get(id);} @PostMapping("/{id}/approve") public WorkflowDetailsResponse approve(@PathVariable UUID id,@Valid @RequestBody WorkflowApprovalRequest request){return engine.approve(id,request);} @PostMapping("/{id}/retry") public WorkflowDetailsResponse retry(@PathVariable UUID id){return engine.retry(id);} @PostMapping("/{id}/rollback") public WorkflowDetailsResponse rollback(@PathVariable UUID id){return engine.rollback(id);} }
